const rss = items[0].json?.rss?.channel?.item;
if (!rss) return [];

const events = Array.isArray(rss) ? rss : [rss];

function mapEventType(title = "") {
  const t = title.toUpperCase();
  if (t.includes("EARTHQUAKE") || t.includes("EQ")) return "EQ";
  if (t.includes("CYCLONE") || t.includes("HURRICANE") || t.includes("TYPHOON")) return "TC";
  if (t.includes("FLOOD")) return "FL";
  if (t.includes("VOLCANO") || t.includes("ERUPTION")) return "VO";
  return "OTHER";
}

return events.map(e => {
  const point = e['georss:point']?.split(' ') || [];

  return {
    json: {
      eventid: String(e.guid || e.link || Math.random()),
      eventtype: mapEventType(e.title),
      eventdate: e.pubDate ? new Date(e.pubDate).toISOString() : null,
      latitude: point.length === 2 ? Number(point[0]) : null,
      longitude: point.length === 2 ? Number(point[1]) : null,
      source: "GDACS",
      raw: e
    }
  };
});
